  "recovered_c": "uint64_t fn_14(uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < (len + 2) / 3 << 2) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n\n  size_t i = 0;\n  while (i + 3 <= len) {\n    uint uVar4 = (uint)in[i] << 0x10 | (uint)in[i + 1] << 8;\n    uint8_t bVar2 = in[i + 2];\n    out[i / 3 * 4] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[in[i] >> 2];\n    out[i / 3 * 4 + 1] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(uVar4 & 0x3f000) >> 0xc];\n    out[i / 3 * 4 + 2] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(bVar2 | uVar4) >> 6 & 0x3f];\n    out[i / 3 * 4 + 3] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[bVar2 & 0x3f];\n    i += 3;\n  }\n\n  if (len - i == 1) {\n    uint8_t bVar2 = in[i];\n    out[i / 3 * 4] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[bVar2 >> 2];\n    out[i / 3 * 4 + 1] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(bVar2 & 3) << 4];\n    out[i / 3 * 4 + 2] = '=';\n    out[i / 3 * 4 + 3] = '=';\n  } else if (len - i == 2) {\n    uint8_t bVar2 = in[i];\n    uint8_t bVar3 = in[i + 1];\n    out[i / 3 * 4] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[bVar2 >> 2];\n    out[i / 3 * 4 + 1] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[((uint)bVar3 << 8 | (uint)bVar2 << 0x10) >> 0xc & 0x3f];\n    out[i / 3 * 4 + 2] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[((uint)bVar3 << 8 & 0xfc0) >> 6];\n    out[i / 3 * 4 + 3] = '=';\n  }\n\n  return i / 3 * 4;\n}"
